using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Demo5.FrontEnd;
public static class IntegrateWorktrees {
 public static string Prepare(){if(EditorApplication.isPlaying)throw new Exception("Stop play mode before merge.");if(EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Active scene has unsaved edits; preserve them first.");AssetDatabase.DisallowAutoRefresh();EditorApplication.LockReloadAssemblies();return "Auto refresh and assembly reload suspended for atomic file integration.";}
 public static string Import(){AssetDatabase.AllowAutoRefresh();EditorApplication.UnlockReloadAssemblies();AssetDatabase.Refresh();return "Refresh resumed; imports and compilation requested.";}
 public static string Validate(){var g=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Settlement/SettlementScreen.prefab");var c=g.GetComponent<SettlementController>();if(!c.Opening||!c.Opening.RecordsView||!c.Opening.NightView)throw new Exception("Opening references missing");if(c.ArrivalPanel.Loot.Sites.Length!=9||c.ArrivalPanel.ObjectNames.Length!=9||c.ArrivalPanel.Search.ObjectIcons.Length!=9||CampaignPersistence.SiteIds.Length!=9)throw new Exception("Latest field site lost");if(CampaignPersistence.CurrentVersion!=14)throw new Exception("Save version lost");var missing=g.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));if(missing!=0)throw new Exception("Missing scripts: "+missing);return "PASS opening/records/night references, 9 exploration sites/icons/names, save v14, no missing scripts.";}
}
